// filterQuery is the dashboard's filter as a query for the cards page, for one
// level or ("") all.
func filterQuery(d Dashboard, level string) string {
	q := url.Values{}
	if level != "" {
		q.Set("level", level)
	}
	if d.Club != "" {
		q.Set("club", d.Club)
	}
	if d.ProblemsOnly {
		q.Set("problems", "1")
	}
	if len(q) == 0 {
		return ""
	}
	return "?" + q.Encode()
}

